            </el-input>
          </div>
          <span class="data-count">共 {{ equipments.length }} 条设备</span>
        </div>
        <div class="toolbar-right">
          <el-button type="primary" @click="handleAdd" v-if="currentUser?.permissions?.includes('manage_equipments')" class="feishu-btn-primary">
            <svg class="btn-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
              <line x1="12" y1="5" x2="12" y2="19"/>
              <line x1="5" y1="12" x2="19" y2="12"/>
            </svg>
            新增设备
          </el-button>
        </div>
      </div>

      <!-- 数据表格卡片 -->
      <div class="table-card">
        <el-table :data="equipments" stripe class="feishu-table desktop-table" :header-cell-style="{ background: '#fafafa', color: '#1f1f1f', fontWeight: '600', fontSize: '14px' }">
          <el-table-column prop="code" label="设备编号" width="140" />
          <el-table-column prop="name" label="设备名称" width="180">
            <template #default="{ row }">
              <div class="equipment-name">
                <span class="name-text">{{ row.name }}</span>
              </div>
            </template>
          </el-table-column>
          <el-table-column label="库存" width="120">
            <template #default="{ row }">
              <div class="stock-info">
                <span class="stock-available">{{ row.available_quantity }}</span>
                <span class="stock-separator">/</span>
                <span class="stock-total">{{ row.total_quantity }}</span>
              </div>
            </template>
          </el-table-column>
          <el-table-column prop="category_name" label="分类" width="120" />
          <el-table-column prop="brand" label="品牌" width="100" />
          <el-table-column prop="model" label="型号" width="100" />
          <el-table-column label="状态" width="100">
            <template #default="{ row }">
              <el-tag :type="getStatusType(row.status)" class="status-tag" :class="'status-' + row.status">
                {{ getStatusText(row.status) }}
              </el-tag>
            </template>
          </el-table-column>
          <el-table-column prop="location" label="存放位置" width="140" />
          <el-table-column label="操作" fixed="right" width="220">
            <template #default="{ row }">
              <div class="action-buttons">
                <el-button
                  size="small"
                  link
                  type="success"
                  class="action-btn borrow"
                  :disabled="row.available_quantity <= 0"
                  @click="handleBorrow(row)"
                >
                  借用
                </el-button>
                <el-button
                  size="small"
                  link
                  type="warning"
                  class="action-btn repair"
                  :disabled="row.available_quantity <= 0"
                  @click="handleReportFault(row)"
                  v-if="currentUser?.permissions?.includes('manage_equipments')"
                >
                  报修
                </el-button>
                <el-button
                  size="small"
                  link
                  type="primary"
                  class="action-btn complete"
                  :disabled="row.available_quantity === row.total_quantity"
                  @click="handleRepairComplete(row)"
                  v-if="currentUser?.permissions?.includes('manage_equipments')"
                >
                  维修完成
                </el-button>
                <el-button
                  size="small"
                  link
                  type="primary"
                  class="action-btn edit"
                  @click="handleEdit(row)"
                  v-if="currentUser?.permissions?.includes('manage_equipments')"
                >
                  编辑
                </el-button>
                <el-button
                  size="small"
                  link
                  type="danger"
                  class="action-btn delete"
                  @click="handleDelete(row)"
                  v-if="currentUser?.permissions?.includes('manage_equipments')"
                >
                  删除
                </el-button>
              </div>
            </template>
          </el-table-column>
        </el-table>

        <div class="mobile-card-list">
          <div v-for="row in equipments" :key="row.id" class="mobile-equipment-card">
            <div class="mobile-card-header">
              <div class="mobile-card-title">
                <div class="mobile-name">{{ row.name }}</div>
                <div class="mobile-subtitle">{{ row.code }}</div>
              </div>
              <el-tag :type="getStatusType(row.status)" class="status-tag" :class="'status-' + row.status">
                {{ getStatusText(row.status) }}
              </el-tag>
            </div>

            <div class="mobile-card-grid">
              <div class="mobile-meta-item">
                <span class="mobile-meta-label">库存</span>
                <span class="mobile-meta-value">{{ row.available_quantity }}/{{ row.total_quantity }}</span>
              </div>
              <div class="mobile-meta-item">
                <span class="mobile-meta-label">分类</span>
                <span class="mobile-meta-value">{{ row.category_name || '-' }}</span>
              </div>
              <div class="mobile-meta-item">
                <span class="mobile-meta-label">品牌</span>
                <span class="mobile-meta-value">{{ row.brand || '-' }}</span>
              </div>
              <div class="mobile-meta-item">
                <span class="mobile-meta-label">型号</span>
                <span class="mobile-meta-value">{{ row.model || '-' }}</span>
              </div>
            </div>

            <div class="mobile-location">{{ row.location || '未设置存放位置' }}</div>

            <div class="mobile-action-group">
              <el-button
                size="small"
                type="success"
                plain
                class="mobile-action-btn"
                :disabled="row.available_quantity <= 0"
                @click="handleBorrow(row)"
              >
                借用
              </el-button>
              <el-button
                size="small"
                type="warning"
                plain
                class="mobile-action-btn"
                :disabled="row.available_quantity <= 0"
                @click="handleReportFault(row)"
                v-if="currentUser?.permissions?.includes('manage_equipments')"
              >
                报修
              </el-button>
              <el-button
                size="small"
                type="primary"
                plain
                class="mobile-action-btn"
                :disabled="row.available_quantity === row.total_quantity"
                @click="handleRepairComplete(row)"
                v-if="currentUser?.permissions?.includes('manage_equipments')"
              >
                维修完成
              </el-button>
              <el-button
                size="small"
                type="primary"
                plain
                class="mobile-action-btn"
                @click="handleEdit(row)"
                v-if="currentUser?.permissions?.includes('manage_equipments')"
              >
                编辑
              </el-button>
              <el-button
                size="small"
                type="danger"
                plain
                class="mobile-action-btn"
                @click="handleDelete(row)"
                v-if="currentUser?.permissions?.includes('manage_equipments')"
              >
                删除
              </el-button>
            </div>
          </div>
        </div>
      </div>
    </div>

    <!-- 借用设备对话框 -->
    <el-dialog
      v-model="borrowDialogVisible"
      title="借用设备"
      width="480px"
      class="feishu-dialog"
      :close-on-click-modal="false"
    >
      <div class="dialog-form">
        <div class="form-item">
          <label class="form-label">设备名称</label>
          <div class="form-value">{{ selectedEquipment?.name }}</div>
        </div>
        <div class="form-item">
          <label class="form-label">借用人</label>
          <div class="form-value">{{ currentUser?.name }}</div>
        </div>
        <el-form :model="borrowForm" label-position="top" ref="borrowFormRef" :rules="borrowRules">
          <el-form-item label="预计归还时间" prop="expected_return_date" class="feishu-form-item">
            <el-date-picker
              v-model="borrowForm.expected_return_date"
              type="datetime"
              placeholder="选择预计归还时间"
              style="width: 100%"
              class="feishu-date-picker"
            />
          </el-form-item>
          <el-form-item label="审批人" prop="approver" class="feishu-form-item">
            <el-select v-model="borrowForm.approver" placeholder="请选择审批老师" style="width: 100%" class="feishu-select">
              <el-option
                v-for="user in approverUsers"
                :key="user.id"
                :label="`${user.name} (${user.username || '未知'})`"
                :value="user.id"
              />
            </el-select>
          </el-form-item>
          <el-form-item label="借用用途" prop="purpose" class="feishu-form-item">
            <el-input
              v-model="borrowForm.purpose"
              type="textarea"
              :rows="3"
              placeholder="请输入借用用途"
              class="feishu-textarea"
            />
          </el-form-item>
        </el-form>
      </div>
      <template #footer>
        <div class="dialog-footer">
          <el-button @click="borrowDialogVisible = false" class="feishu-btn-default">取消</el-button>
          <el-button type="primary" @click="submitBorrow" class="feishu-btn-primary">确定借用</el-button>
        </div>
      </template>
    </el-dialog>

    <!-- 设备表单对话框 -->
    <el-dialog
      v-model="dialogVisible"
      :title="isEdit ? '编辑设备' : '新增设备'"
      width="520px"
      class="feishu-dialog"
      :close-on-click-modal="false"
    >
      <el-form :model="form" label-position="top" ref="formRef" :rules="rules" class="feishu-form">
        <div class="form-row">
          <el-form-item label="设备名称" prop="name" class="feishu-form-item">
            <el-input v-model="form.name" placeholder="请输入设备名称" class="feishu-input" />
          </el-form-item>
          <el-form-item label="设备编号" prop="code" class="feishu-form-item">
            <el-input v-model="form.code" placeholder="请输入唯一编号" class="feishu-input" />
          </el-form-item>
        </div>
        <div class="form-row">
          <el-form-item label="总数量" prop="total_quantity" class="feishu-form-item">
            <el-input-number v-model="form.total_quantity" :min="1" @change="handleTotalQuantityChange" class="feishu-number" />
          </el-form-item>
          <el-form-item label="在库数量" prop="available_quantity" class="feishu-form-item">
            <el-input-number v-model="form.available_quantity" :min="0" :max="form.total_quantity" class="feishu-number" />
          </el-form-item>
        </div>
        <el-form-item label="设备分类" prop="category" class="feishu-form-item">
          <el-select v-model="form.category" placeholder="请选择分类" style="width: 100%" class="feishu-select">
            <el-option
              v-for="item in categories"
              :key="item.id"
              :label="item.name"
              :value="item.id"
            />
          </el-select>
        </el-form-item>
        <div class="form-row">
          <el-form-item label="品牌" prop="brand" class="feishu-form-item">
            <el-input v-model="form.brand" placeholder="请输入品牌" class="feishu-input" />
          </el-form-item>
          <el-form-item label="型号" prop="model" class="feishu-form-item">
            <el-input v-model="form.model" placeholder="请输入型号" class="feishu-input" />
          </el-form-item>
        </div>
        <el-form-item label="序列号" prop="serial_number" class="feishu-form-item">
          <el-input v-model="form.serial_number" placeholder="请输入设备序列号(S/N)" class="feishu-input" />
        </el-form-item>
        <el-form-item label="存放位置" prop="location" class="feishu-form-item">
          <el-input v-model="form.location" placeholder="请输入存放位置" class="feishu-input" />
        </el-form-item>
        <el-form-item label="状态" prop="status" class="feishu-form-item">
          <el-select v-model="form.status" style="width: 100%" class="feishu-select">
            <el-option
              v-for="status in meta.equipment_statuses"
              :key="status.code"
              :label="status.label"
              :value="status.code"
            />
          </el-select>
        </el-form-item>
      </el-form>
      <template #footer>
        <div class="dialog-footer">
          <el-button @click="dialogVisible = false" class="feishu-btn-default">取消</el-button>
          <el-button type="primary" @click="submitForm" class="feishu-btn-primary">确定</el-button>
        </div>
      </template>
    </el-dialog>
  </div>
</template>

<script setup>
import { ref, onMounted, reactive, computed } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { Box } from '@element-plus/icons-vue'
import api from '@/api'

const router = useRouter()
const equipments = ref([])
const categories = ref([])
const profiles = ref([])
const currentUser = ref(null)
const searchText = ref('')
const dialogVisible = ref(false)
const borrowDialogVisible = ref(false)
const isEdit = ref(false)
const formRef = ref(null)
const borrowFormRef = ref(null)

const selectedEquipment = ref(null)

const form = reactive({
  id: null,
  name: '',
  code: '',
  total_quantity: 1,
  available_quantity: 1,
  serial_number: '',
  category: '',
  brand: '',
  model: '',
  location: '',
  status: 'available'
})

const handleTotalQuantityChange = (val) => {
  if (!isEdit.value) {
    form.available_quantity = val
  }
}

const borrowForm = reactive({
  approver: '',
  expected_return_date: '',
  purpose: ''
})

const borrowRules = {
  approver: [{ required: true, message: '请选择审批人', trigger: 'change' }],
  expected_return_date: [{ required: true, message: '请选择预计归还时间', trigger: 'change' }],
  purpose: [{ required: true, message: '请输入借用用途', trigger: 'blur' }]
}

const approverUsers = computed(() => {
  return profiles.value.filter(u =>
    u.role === '教师' || u.role === '管理员' || u.role === 'teacher' || u.role === 'admin'
  )
})

const rules = {
  name: [{ required: true, message: '请输入设备名称', trigger: 'blur' }],
  code: [{ required: true, message: '请输入设备编号', trigger: 'blur' }],
  serial_number: [{ required: true, message: '请输入序列号', trigger: 'blur' }],
  category: [{ required: true, message: '请选择分类', trigger: 'change' }],
  model: [{ required: true, message: '请输入型号', trigger: 'blur' }],
  location: [{ required: true, message: '请输入存放位置', trigger: 'blur' }]
}

const fetchEquipments = async () => {
  try {
    const params = {}
    if (searchText.value) {
      params.search = searchText.value
    }
    const response = await api.getEquipments(params)
    let data = response.data
    equipments.value = data.results || data || []
  } catch (error) {
    ElMessage.error('获取设备列表失败')
    equipments.value = []
  }
}

const fetchCategories = async () => {
  try {
    const response = await api.getCategories()
    categories.value = response.data.results || response.data || []
  } catch (error) {
    console.error('获取分类失败')
  }
}

const fetchProfiles = async () => {
  try {
    const res = await api.getUsers({ role: 'teacher' })
    profiles.value = res.data.results || res.data || []
  } catch (error) {
    console.error('获取用户列表失败')
  }
}

const meta = ref({ equipment_statuses: [] })
const equipmentStatusLabelMap = computed(() => {
  const m = {}
  for (const s of (meta.value.equipment_statuses || [])) {
    if (s && s.code) m[s.code] = s.label
  }
  return m
})

const getStatusType = (status) => {
  const map = { available: 'success', borrowed: 'warning', maintaining: 'info', repairing: 'danger', scrapped: 'info', reserved: 'warning', demo: 'info' }
  return map[status] || 'info'
}

const getStatusText = (status) => {
  return equipmentStatusLabelMap.value[status] || status
}

const goBack = () => {
  router.push('/')
}

const handleSearch = () => {
  fetchEquipments()
}

const handleBorrow = (row) => {
  selectedEquipment.value = row
  Object.assign(borrowForm, {
    approver: '',
    expected_return_date: '',
    purpose: ''
  })
  borrowDialogVisible.value = true
}

const handleReportFault = (row) => {
  ElMessageBox.prompt('请输入故障描述', '设备报修', {
    confirmButtonText: '确定',
    cancelButtonText: '取消',
  }).then(async ({ value }) => {
    try {
      await api.reportFault(row.id, { description: value })
      ElMessage.success('报修成功')
      fetchEquipments()
    } catch (error) {
      ElMessage.error('报修失败')
    }
  })
}

const handleRepairComplete = async (row) => {
  try {
    await api.repairComplete(row.id)
    ElMessage.success('设备维修完成，库存已恢复')
    fetchEquipments()
  } catch (error) {
    ElMessage.error('操作失败')
  }
}

const submitBorrow = async () => {
  if (!borrowFormRef.value) return
  await borrowFormRef.value.validate(async (valid) => {
    if (valid) {
      try {
        const approvalData = {
          title: `${currentUser.value.name} 申请借用 ${selectedEquipment.value.name}`,
          content: `借用用途: ${borrowForm.purpose}`,
          type: 'equipment_borrow',
          applicant_user_id: currentUser.value.user?.id || currentUser.value.id,
          approver_user_id: borrowForm.approver,
          extra_data: {
            equipment_id: selectedEquipment.value.id,
            borrower_id: currentUser.value.id,
            expected_return_date: borrowForm.expected_return_date,
            purpose: borrowForm.purpose
          }
        }

        await api.createApproval(approvalData)
        ElMessage.success('借用申请已提交，请等待审批')
        borrowDialogVisible.value = false
      } catch (error) {
        ElMessage.error(api.getErrorMessage(error, '申请提交失败'))
      }
    }
  })
}

const handleAdd = () => {
  isEdit.value = false
  Object.assign(form, {
    id: null,
    name: '',
    code: '',
    total_quantity: 1,
    available_quantity: 1,
    serial_number: '',
    category: '',
    brand: '',
    model: '',
    location: '',
    status: 'available'
  })
  dialogVisible.value = true
}

const handleEdit = (row) => {
  isEdit.value = true
  Object.assign(form, {
    id: row.id,
    name: row.name,
    code: row.code,
    total_quantity: row.total_quantity,
    available_quantity: row.available_quantity,
    serial_number: row.serial_number,
    category: row.category,
    brand: row.brand,
    model: row.model,
    location: row.location,
    status: row.status
  })
  dialogVisible.value = true
}

const handleDelete = (row) => {
  ElMessageBox.confirm(`确定要删除设备 "${row.name}" 吗？`, '提示', {
    confirmButtonText: '确定',
    cancelButtonText: '取消',
    type: 'warning'
  }).then(async () => {
    try {
      await api.deleteEquipment(row.id)
      ElMessage.success('删除成功')
      fetchEquipments()
    } catch (error) {
      ElMessage.error('删除失败')
    }
  })
}

const submitForm = async () => {
  if (!formRef.value) return
  await formRef.value.validate(async (valid) => {
    if (valid) {
      try {
        if (isEdit.value) {
          await api.updateEquipment(form.id, form)
          ElMessage.success('修改成功')
        } else {
          await api.createEquipment(form)
          ElMessage.success('新增成功')
        }
        dialogVisible.value = false
        fetchEquipments()
      } catch (error) {
        ElMessage.error(isEdit.value ? '修改失败' : '新增失败')
      }
    }
  })
}

onMounted(() => {
  const userStr = localStorage.getItem('user')
  if (userStr) {
    currentUser.value = JSON.parse(userStr)
  }
  api.getMeta().then(r => { meta.value = r.data || {} }).catch(() => {})
  fetchCategories()
  fetchEquipments()
  fetchProfiles()
})
</script>

